repo.tickets.py:
"""Ticket records."""


class Ticket:
    def __init__(self, team, hours):
        self.team = team
        self.hours = hours

    def __repr__(self):
        return "Ticket(%r, %r)" % (self.team, self.hours)


ROWS = [('core', 46), ('web', 10), ('ops', 42), ('web', 14), ('ops', 56), ('core', 6)]


def load_tickets():
    """Yield the stored tickets one at a time."""
    for team, hours in ROWS:
        yield Ticket(team, hours)

