"""A ledger of tickets."""


class TicketLedger:
    def __init__(self, tickets=()):
        self._tickets = list(tickets)

    def tickets(self):
        """Return the tickets held (a copy, so callers cannot change the ledger)."""
        return list(self._tickets)

    def add(self, ticket):
        """Add one ticket to the ledger."""
        self.tickets().append(ticket)

    def total(self):
        """Return the total hours of the tickets held."""
        return sum(x.hours for x in self._tickets)

